                    sessions[sid]['has_dm'] = True
                    break
            except:
                pass

non_dm = [info['file'] for info in sessions.values() if not info['has_dm']]
for f in non_dm:
    os.remove(f)
    # 清理空目录
    d = os.path.dirname(f)
    if not os.listdir(d):
        os.rmdir(d)

print(f'已删除 {len(non_dm)} 个无关会话')
